PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT DEFAULT '',address TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id INTEGER NOT NULL REFERENCES customers(id),date TEXT NOT NULL,fx REAL NOT NULL,delivered INTEGER NOT NULL DEFAULT 0,customer_paid INTEGER NOT NULL DEFAULT 0,supplier_paid INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,name TEXT NOT NULL,qty REAL NOT NULL,sell REAL NOT NULL,sell_currency TEXT NOT NULL CHECK(sell_currency IN('USD','LBP')),buy REAL NOT NULL,buy_currency TEXT NOT NULL CHECK(buy_currency IN('USD','LBP')));
CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,description TEXT NOT NULL,date TEXT NOT NULL,amount REAL NOT NULL,currency TEXT NOT NULL CHECK(currency IN('USD','LBP')),fx REAL NOT NULL,notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fx_history(id INTEGER PRIMARY KEY AUTOINCREMENT,old_rate REAL NOT NULL,new_rate REAL NOT NULL,changed_at TEXT NOT NULL);
INSERT OR IGNORE INTO settings(key,value) VALUES('fx','90000');
